package sn.ucad.nexora.espace.presentation.controller;
import java.util.List; import java.util.UUID; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import sn.ucad.nexora.espace.application.dto.request.CreateEspaceRequest; import sn.ucad.nexora.espace.application.dto.request.UpdateEspaceRequest; import sn.ucad.nexora.espace.application.dto.response.EspaceResponse; import sn.ucad.nexora.espace.application.usecase.CreateEspaceUseCase; import sn.ucad.nexora.espace.application.usecase.DeleteEspaceUseCase; import sn.ucad.nexora.espace.application.usecase.GetEspaceUseCase; import sn.ucad.nexora.espace.application.usecase.UpdateEspaceUseCase; import sn.ucad.nexora.espace.infrastructure.persistence.AdresseLookupRepository; import sn.ucad.nexora.espace.infrastructure.persistence.EspaceJpaRepository; import sn.ucad.nexora.espace.infrastructure.persistence.PhotoEspaceRepository; import sn.ucad.nexora.espace.infrastructure.persistence.entity.PhotoEspaceJpaEntity; import sn.ucad.nexora.espace.presentation.mapper.EspacePresentationMapper; import org.springframework.security.core.Authentication; import sn.ucad.nexora.common.exception.ResourceNotFoundException; import sn.ucad.nexora.espace.infrastructure.persistence.moderation.ModerationEspaceRepository; import sn.ucad.nexora.espace.domain.entity.EspaceProfessionnel;
@RestController @RequestMapping("/api/v1/espaces") public class EspaceController{private final CreateEspaceUseCase create;private final GetEspaceUseCase get;private final UpdateEspaceUseCase update;private final DeleteEspaceUseCase delete;private final AdresseLookupRepository adresses;private final PhotoEspaceRepository photos;private final EspaceJpaRepository espaces;private final EspacePresentationMapper mapper;private final ModerationEspaceRepository moderation;public EspaceController(CreateEspaceUseCase c,GetEspaceUseCase g,UpdateEspaceUseCase u,DeleteEspaceUseCase d,AdresseLookupRepository a,PhotoEspaceRepository p,EspaceJpaRepository e,EspacePresentationMapper m,ModerationEspaceRepository mo){create=c;get=g;update=u;delete=d;adresses=a;photos=p;espaces=e;mapper=m;moderation=mo;}
 private List<String> photosDe(Long id){return photos.findByEspaceIdOrderByOrdreAffichageAsc(id).stream().map(PhotoEspaceJpaEntity::getUrl).toList();}
 @PostMapping public ResponseEntity<EspaceResponse> create(@AuthenticationPrincipal UUID accountId,@Valid @RequestBody CreateEspaceRequest r){var espace=create.create(accountId,r);var adresse=adresses.findPrincipaleByEspaceId(espace.getId()).orElse(null);return ResponseEntity.status(201).body(mapper.toResponse(espace,adresse,photosDe(espace.getId())));}

 /**
  * Fiche d'un espace. Publique pour un espace ACTIF ; un espace suspendu (ou pas encore actif) n'est
  * visible que de son propriétaire et de la modération, avec le motif (§9.9) : pour tous les autres
  * il est « introuvable », comme dans la recherche.
  */
 @GetMapping("/{id}") public ResponseEntity<EspaceResponse> get(@PathVariable Long id,Authentication auth){var espace=get.get(id);boolean actif="ACTIF".equals(espace.getStatut());if(!actif&&!peutVoirNonActif(espace,auth))throw new ResourceNotFoundException("Espace introuvable");var adresse=adresses.findPrincipaleByEspaceId(id).orElse(null);var r=mapper.toResponse(espace,adresse,photosDe(id));if(!actif)avecModeration(r);return ResponseEntity.ok(r);}
 private boolean peutVoirNonActif(EspaceProfessionnel espace,Authentication auth){if(auth==null||!(auth.getPrincipal() instanceof UUID compte))return false;if(auth.getAuthorities().stream().anyMatch(a->"PERM_MODERER_ESPACES".equals(a.getAuthority())))return true;return moderation.utilisateurId(compte).map(u->u.equals(espace.getUtilisateurId())).orElse(false);}
 private EspaceResponse avecModeration(EspaceResponse r){moderation.moderationVisible(r.getId()).ifPresent(m->{r.setMotifModeration(m.motif());r.setDateModeration(m.date());});return r;}
 @PostMapping("/{id}/vue") public ResponseEntity<Void> enregistrerVue(@PathVariable Long id){espaces.incrementerVues(id);return ResponseEntity.noContent().build();}
 @GetMapping("/me") public ResponseEntity<List<EspaceResponse>> mine(@AuthenticationPrincipal UUID accountId){return ResponseEntity.ok(get.mine(accountId).stream().map(mapper::toResponse).map(r->"ACTIF".equals(r.getStatut())?r:avecModeration(r)).toList());}
 @PutMapping("/{id}") public ResponseEntity<EspaceResponse> update(@AuthenticationPrincipal UUID accountId,@PathVariable Long id,@Valid @RequestBody UpdateEspaceRequest r){var espace=update.update(accountId,id,r);var adresse=adresses.findPrincipaleByEspaceId(id).orElse(null);return ResponseEntity.ok(mapper.toResponse(espace,adresse,photosDe(id)));}
 @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@AuthenticationPrincipal UUID accountId,@PathVariable Long id){delete.supprimer(accountId,id);return ResponseEntity.noContent().build();}
}
